def run_site_reset_in_loop(iterations=1, timeout=720, multi_bts_dict=None, target=None, **kwargs):
    """
    Run Site Reset in Loop.

    :param iterations:  number of iterations
    :param timeout:     timeout for 'wait_for_all_cells_onair' after reset
    :param target:      targets for calculated KPIS: could be passed as dict:
                        TARGETS = {
                            'kpi1a': 600,
                            'kpi1b': 600,
                            'kpi1c': 600,
                        }
    :param kwargs: kwargs, that will be transferred to taf.rfrl.procedures.resources.python.OAM_KPI.GenericKPIRunner
    :param multi_bts_dict: dict, with parameters to another BTS, example:
    {"GNB1_DU0":
         {"kwargs":
              {"bts_id": 1,
               "du_id": 0,
               "collect_passed_snapshot": False,
               "calculate_kpi": False,
               "collect_ru_logs": True,
               "add_default_logs": False,
               "additional_allowed_alarms": '${ALLOWED_ALARMS_SLAVE}',
               "temp_allowed_alarms": '${TEMPORARY_ALLOWED_AlARMS_SLAVE}',
               "critical_alarms": '${CRITICAL_AlARMS}',
               "temp_critical_alarms": '${TEMPORARY_CRITICAL_AlARMS}}',
               "excluded_functions": ["run_operation"]
               }
          }
     }
     where 'excluded_functions stands' for functions that will be not run in given BTS, possible functions:
     actions_before_loop, run_preconditions, checks_before_operation, actions_before_operation, run_operation,
     actions_after_operation, checks_after_operation, actions_when_bts_did_not_go_on_air, run_postconditions,
     check_status_after_run, actions_after_loop
    :return: dict: calculated KPIs from each iterations
                    results = {
                        'kpi1a': {
                            'avg': 470.999,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 451.932, 'status': 'PASSED'},
                                        {'delta': 490.066, 'status': 'PASSED'}],
                            'target': 600.0},
                        'kpi1b': {
                            'avg': 470.999,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 451.932, 'status': 'PASSED'},
                                        {'delta': 490.066, 'status': 'PASSED'}],
                            'target': 600.0},
                        'kpi1c': {
                            'avg': 468.1325,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 447.836, 'status': 'PASSED'},
                                        {'delta': 488.429, 'status': 'PASSED'}],
                            'target': 600.0}}
    """
    if multi_bts_dict:
        obj = convert_to_robot_kw(SiteResetRunnerMultiBTS, multi_bts_dict=multi_bts_dict, **kwargs)
    else:
        obj = convert_to_robot_kw(SiteResetRunner, **kwargs)
    return convert_to_robot_kw(obj.run_in_loop, iterations=iterations, timeout=timeout, target=target)


