def run_sw_upgrade_in_loop(target_builds, target_dir, source_build, timeout=720, target=None, iterations=1,
                           sw_upgrade_kwargs={}, rollback_kwargs={}):
    """
    Run Software Upgrade in loop.

    :param target_builds: list, target builds to be upgraded on bts
    :param source_build: build that will be rollback performed to
    :param target_dir:  target directory
    :param timeout:     timeout for 'wait_for_all_cells_onair' after reset
    :param target:      targets for calculated KPIS: could be passed as dict:
                        TARGETS = {
                            'kpi2a': 600,
                            'kpi2b': 600,
                            'kpi2c': 600,
                            'kpi2d': 600,
                        }
    :param start_iteration: use to specify log directory
    :param iterations: used for specify log directory(WARNING: should be same value as start_iteration)
    :param sw_upgrade_kwargs: kwargs to SwUpgradeRunner:
        :param kpi_names: list with kpi names, WARNING: insertion of bad kpi names can cause faults and bad results.
        :param check_passive: If True, before operation the build on passive partition is checked if is
        same sa source_build
    :param rollback_kwargs: kwargs to RollbackRunner:
        :param check_source_build: If True, after operation the build on active partition is checked if is
        same sa sw_version
    :return: dict: calculated KPIs from each iterations
                    results = {
                        'kpi2a': {
                            'avg': 65.5025,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 61.002, 'status': 'PASSED'},
                                        {'delta': 70.003, 'status': 'PASSED'}],
                            'target': 600.0}}
    """
    test_name = BuiltIn().get_variable_value("${TEST NAME}")
    BuiltIn().set_test_variable("${TEST NAME}", str(test_name) + "_software_upgrade")
    if "multi_bts_dict" in sw_upgrade_kwargs.keys():
        upgrade_obj = convert_to_robot_kw(SwUpgradeRunnerMultiBTS, sw_version=None, target_dir=target_dir,
                                          **sw_upgrade_kwargs)
    else:
        upgrade_obj = convert_to_robot_kw(SwUpgradeRunner, sw_version=None, target_dir=target_dir, **sw_upgrade_kwargs)
    BuiltIn().set_test_variable("${TEST NAME}", str(test_name) + "_software_rollback")
    if "multi_bts_dict" in rollback_kwargs.keys():
        rollback_obj = convert_to_robot_kw(RollbackRunnerMultiBTS, sw_version=source_build, **rollback_kwargs)
    else:
        rollback_obj = convert_to_robot_kw(RollbackRunner, sw_version=source_build, **rollback_kwargs)
    with RobotWrapper(wrap_name="Software upgrade/rollback FOR LOOP, ITERATIONS: {}".format(iterations),
                      wrap_type="for") as wrapper:
        for iteration in range(0, iterations):
            upgrade_build = target_builds[iteration % len(target_builds)]
            wrapper.create_level("Software upgrade/rollback iteration {}, build: {}".format(iteration, upgrade_build),
                                 wrap_type="foritem", level=2)
            upgrade_obj.sw_version = upgrade_build
            try:
                convert_to_robot_kw(upgrade_obj.run_in_loop, iterations=iteration + 1, timeout=timeout, target=target,
                                    start_iteration=iteration + 1)
            except Exception as ex:
                if "Execution terminated by signal" in str(ex) or "Passive SW and target SW are the same" in str(ex):
                    break
            try:
                convert_to_robot_kw(rollback_obj.run_in_loop, iterations=iteration + 1, timeout=timeout, target=target,
                                    start_iteration=iteration + 1)
            except Exception as ex:
                if "Execution terminated by signal" in str(ex):
                    break


